def _repair_catalogue_text(text: str) -> str:
    """Repair UTF-8 text that the app catalogue stored as Windows-1252."""
    if "\u00c3" not in text and "\u00c2" not in text:
        return text
    try:
        return text.encode("cp1252").decode("utf-8")
    except UnicodeError:
        return text


def _load_tutorial_catalog() -> tuple[
    dict[str, tuple[OfficialAssociationStep, ...]], dict[str, str]
]:
    """Decode the official product tutorial catalogue and its identifiers."""
    payload = json.loads(
        gzip.decompress(base64.b64decode(_COMPRESSED_CATALOG)).decode("utf-8")
    )
    tutorials = payload["tutorials"]
    return (
        {
            product: tuple(
                OfficialAssociationStep(
                    text=_repair_catalogue_text(step["text"]),
                    starts_gateway_listening=step["launch"],
                )
                for step in tutorials[tutorial_id]
                if step["text"]
            )
            for product, tutorial_id in payload["models"].items()
            if tutorial_id in tutorials and tutorials[tutorial_id]
        },
        dict(payload["models"]),
    )


(
    OFFICIAL_ASSOCIATION_TUTORIALS,
    OFFICIAL_ASSOCIATION_TUTORIAL_IDS,
) = _load_tutorial_catalog()

def get_official_association_tutorial_id(product: str | None) -> str | None:
    """Return the official tutorial identifier selected for a product."""
    if product is None:
        return None
    return OFFICIAL_ASSOCIATION_TUTORIAL_IDS.get(product)



