def _load_standard_illustrations() -> tuple[
    dict[str, tuple[str, ...]], dict[str, str]
]:
    """Decode official illustration sequences for standard products."""
    payload = json.loads(
        gzip.decompress(base64.b64decode(_COMPRESSED_STANDARD_ILLUSTRATIONS)).decode(
            "utf-8-sig"
        )
    )
    return (
        {key: tuple(value) for key, value in payload["tutorials"].items()},
        payload["vectors"],
    )


_STANDARD_TUTORIAL_ILLUSTRATIONS, _STANDARD_ILLUSTRATION_VECTORS = (
    _load_standard_illustrations()
)


