def _load_exact_standard_illustrations() -> tuple[
    dict[str, tuple[str, ...]], dict[str, str]
]:
    """Decode exact official visual sequences and their missing vectors."""
    payload = json.loads(
        gzip.decompress(
            base64.b64decode(_COMPRESSED_EXACT_STANDARD_ILLUSTRATIONS)
        ).decode("utf-8-sig")
    )
    return (
        {key: tuple(value) for key, value in payload["tutorials"].items()},
        payload["vectors"],
    )


_EXACT_STANDARD_TUTORIAL_ILLUSTRATIONS, _EXACT_STANDARD_ILLUSTRATION_VECTORS = (
    _load_exact_standard_illustrations()
)


